<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage } from 'element-plus'
import { api, ApiError } from '../api'
import { statusLabel, errorText } from '../utils'
import type { Category, Department, Page, Role, User } from '../types'
const route = useRoute(), kind = computed(() => route.path.split('/').pop() || 'users')
const title = computed(() => ({ users: '用户管理', departments: '部门管理', categories: '工单分类', roles: '角色权限' }[kind.value] || '管理'))
const path = computed(() => `/api/${kind.value === 'categories' ? 'ticket-categories' : kind.value}`)
const loading = ref(false), busy = ref(false), error = ref(''), saveError = ref(''), conflicted = ref(false)
const users = ref<User[]>([]), departments = ref<Department[]>([]), categories = ref<Category[]>([]), roles = ref<Role[]>([]), total = ref(0), page = ref(1)
const keyword = ref(''), status = ref(''), departmentFilter = ref(''), roleFilter = ref('')
const mode = ref(''), selected = ref<User | Department | Category | null>(null)
const form = reactive({ username: '', name: '', code: '', departmentId: '', password: '', roleIds: [] as string[], description: '', defaultDepartmentId: '', status: 'ENABLED' })
const dialogTitle = computed(() => ({ create: `新建${kind.value === 'users' ? '用户' : kind.value === 'categories' ? '分类' : '部门'}`, edit: '编辑资料', roles: '分配角色', password: '重置密码', status: '变更启用状态', detail: '用户详情' }[mode.value] || '管理'))
async function loadOptions() { if (kind.value === 'users' || kind.value === 'categories') departments.value = await api('GET', '/api/departments'); if (kind.value === 'users' || kind.value === 'roles') roles.value = await api('GET', '/api/roles') }
async function load() {
  loading.value = true; error.value = ''
  try {
    await loadOptions()
    if (kind.value === 'users') { const result = await api<Page<User>>('GET', path.value, undefined, { page: page.value, pageSize: 10, name: keyword.value || undefined, status: status.value || undefined, departmentId: departmentFilter.value || undefined, roleId: roleFilter.value || undefined }); users.value = result.records; total.value = result.total }
    else if (kind.value === 'departments') departments.value = await api('GET', path.value, undefined, { name: keyword.value || undefined, status: status.value || undefined })
    else if (kind.value === 'categories') categories.value = await api('GET', path.value, undefined, { name: keyword.value || undefined, status: status.value || undefined })
  } catch (e) { error.value = errorText(e) } finally { loading.value = false }
}
function search() { page.value = 1; void load() }
async function open(operation: string, value?: User | Department | Category) {
  selected.value = value || null; mode.value = operation; saveError.value = ''; conflicted.value = false
  Object.assign(form, { username: '', name: '', code: '', departmentId: '', password: '', roleIds: [], description: '', defaultDepartmentId: '', status: 'ENABLED' })
  if (value) {
    form.name = value.name; form.status = value.status
    if ('username' in value) { form.username = value.username; form.departmentId = value.department?.id || ''; form.roleIds = value.roles.map(r => r.id) }
    if ('code' in value) form.code = value.code
    if ('defaultDepartment' in value) { form.defaultDepartmentId = value.defaultDepartment?.id || ''; form.description = value.description }
    if (operation === 'status') form.status = value.status === 'ENABLED' ? 'DISABLED' : 'ENABLED'
    if (kind.value === 'users' && ['edit', 'detail', 'roles'].includes(operation)) try { selected.value = await api<User>('GET', `/api/users/${value.id}`); const user = selected.value as User; form.name = user.name; form.departmentId = user.department?.id || ''; form.roleIds = user.roles.map(r => r.id) } catch (e) { saveError.value = errorText(e) }
  }
}
async function refreshVersion() { await load(); const value = kind.value === 'users' ? users.value.find(u => u.id === selected.value?.id) : kind.value === 'departments' ? departments.value.find(d => d.id === selected.value?.id) : categories.value.find(c => c.id === selected.value?.id); if (value) { selected.value = value; conflicted.value = false; saveError.value = '已刷新版本，请核对当前数据后再提交。输入已保留。' } else saveError.value = '资源不在当前列表，请关闭后重新查询。' }
async function save() {
  saveError.value = ''
  if (['create','edit'].includes(mode.value) && !form.name.trim()) { saveError.value = '请填写名称'; return }
  if (mode.value === 'create' && kind.value !== 'users' && !form.code.trim()) { saveError.value = '请填写唯一编码'; return }
  if (kind.value === 'users' && ['create','edit'].includes(mode.value) && !form.departmentId) { saveError.value = '请选择部门'; return }
  if (kind.value === 'users' && mode.value === 'create' && (!form.username.trim() || !form.roleIds.length)) { saveError.value = '请填写用户名并选择角色'; return }
  if ((mode.value === 'password' || mode.value === 'create' && kind.value === 'users') && (form.password.length < 8 || form.password.length > 72)) { saveError.value = '密码应为 8–72 个字符'; return }
  if (mode.value === 'roles' && !form.roleIds.length) { saveError.value = '至少选择一个角色'; return }
  if (kind.value === 'categories' && ['create','edit'].includes(mode.value) && !form.defaultDepartmentId) { saveError.value = '请选择默认处理部门'; return }
  busy.value = true
  try {
    const v = selected.value?.version
    if (mode.value === 'status') await api('PUT', `${path.value}/${selected.value!.id}/status`, { status: form.status, version: v })
    else if (mode.value === 'roles') await api('PUT', `/api/users/${selected.value!.id}/roles`, { roleIds: form.roleIds, version: v })
    else if (mode.value === 'password') await api('PUT', `/api/users/${selected.value!.id}/password`, { newPassword: form.password })
    else {
      const body = kind.value === 'users' ? mode.value === 'create' ? { username: form.username, name: form.name, departmentId: form.departmentId, password: form.password, roleIds: form.roleIds } : { name: form.name, departmentId: form.departmentId, version: v } : kind.value === 'categories' ? { name: form.name, ...(mode.value === 'create' ? { code: form.code } : { version: v }), description: form.description, defaultDepartmentId: form.defaultDepartmentId } : { name: form.name, ...(mode.value === 'create' ? { code: form.code } : { version: v }) }
      await api(mode.value === 'create' ? 'POST' : 'PATCH', mode.value === 'create' ? path.value : `${path.value}/${selected.value!.id}`, body)
    }
    ElMessage.success('已保存'); mode.value = ''; await load()
  } catch (e) { saveError.value = errorText(e); conflicted.value = e instanceof ApiError && e.status === 409 } finally { busy.value = false }
}
watch(kind, () => { keyword.value = ''; status.value = ''; departmentFilter.value = ''; roleFilter.value = ''; page.value = 1; mode.value = ''; void load() }, { immediate: true })
</script>
<template><div class="page"><div class="page-header"><div><h1>{{ title }}</h1><p class="subtitle">{{ kind === 'roles' ? '固定角色清晰分工，实际数据访问由服务端权限校验。' : kind === 'categories' ? '将问题送到合适的团队，路由变更仅影响后续新工单。' : '维护组织信息与账号，保持团队协作有序。' }}</p></div><el-button v-if="kind !== 'roles'" type="primary" @click="open('create')">新建{{ kind === 'users' ? '用户' : kind === 'categories' ? '分类' : '部门' }}</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"><template #default><el-button text @click="load">重新加载</el-button></template></el-alert><section class="surface" v-loading="loading"><div v-if="kind !== 'roles'" class="toolbar"><el-input v-model="keyword" clearable placeholder="按名称查询" @keyup.enter="search" @clear="search"/><el-select v-model="status" placeholder="全部状态" clearable @change="search"><el-option label="启用" value="ENABLED"/><el-option label="停用" value="DISABLED"/></el-select><template v-if="kind === 'users'"><el-select v-model="departmentFilter" placeholder="全部部门" clearable @change="search"><el-option v-for="d in departments" :key="d.id" :value="d.id" :label="d.name"/></el-select><el-select v-model="roleFilter" placeholder="全部角色" clearable @change="search"><el-option v-for="r in roles" :key="r.id" :value="r.id" :label="r.name"/></el-select></template><el-button @click="search">查询</el-button><el-button @click="load">刷新</el-button></div><el-table v-if="kind === 'users'" :data="users" empty-text="没有符合条件的用户"><el-table-column label="用户" min-width="150"><template #default="{row}"><el-button link type="primary" @click="open('detail',row)">{{ row.name }}</el-button><div class="muted">{{ row.username }}</div></template></el-table-column><el-table-column label="部门" prop="department.name" min-width="120"/><el-table-column label="角色" min-width="130"><template #default="{row}">{{ row.roles.map((r: Role)=>r.name).join('、') }}</template></el-table-column><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.status==='ENABLED'?'success':'info'" effect="plain">{{ statusLabel(row.status) }}</el-tag></template></el-table-column><el-table-column label="操作" min-width="300"><template #default="{row}"><div class="actions"><el-button link type="primary" @click="open('edit',row)">编辑</el-button><el-button link type="primary" @click="open('roles',row)">分配角色</el-button><el-button link @click="open('password',row)">重置密码</el-button><el-button link :type="row.status==='ENABLED'?'danger':'primary'" @click="open('status',row)">{{ row.status==='ENABLED'?'停用':'启用' }}</el-button></div></template></el-table-column></el-table><el-pagination v-if="kind==='users'" v-model:current-page="page" :total="total" :page-size="10" layout="prev,pager,next" @current-change="load"/><el-table v-else-if="kind==='roles'" :data="roles"><el-table-column label="角色" prop="name" width="140"/><el-table-column label="职责" prop="description" min-width="300"/><el-table-column label="权限标识" min-width="300"><template #default="{row}"><div class="actions"><el-tag v-for="p in row.permissions" :key="p" type="info" size="small" effect="plain">{{ p }}</el-tag></div></template></el-table-column></el-table><el-table v-else :data="kind==='departments'?departments:categories" empty-text="暂无数据"><el-table-column label="名称" prop="name" min-width="180"/><el-table-column label="编码" prop="code" min-width="150"/><el-table-column v-if="kind==='categories'" label="默认处理部门" min-width="150"><template #default="{row}">{{ row.defaultDepartment?.name || '未设置' }}</template></el-table-column><el-table-column v-if="kind==='categories'" label="说明" prop="description" min-width="180"/><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.status==='ENABLED'?'success':'info'" effect="plain">{{ statusLabel(row.status) }}</el-tag></template></el-table-column><el-table-column label="操作" width="150"><template #default="{row}"><el-button link type="primary" @click="open('edit',row)">编辑</el-button><el-button link :type="row.status==='ENABLED'?'danger':'primary'" @click="open('status',row)">{{ row.status==='ENABLED'?'停用':'启用' }}</el-button></template></el-table-column></el-table></section><p class="form-help">{{ kind==='roles'?'角色分配请在用户管理中操作，不提供动态权限编辑。':'停用不删除历史记录；有关联业务时，服务端会提示先完成必要调整。' }}</p><el-dialog :model-value="!!mode" :title="dialogTitle" width="560px" :close-on-click-modal="!busy" @close="mode='' "><el-alert v-if="saveError" :title="saveError" type="warning" :closable="false"><template #default><el-button v-if="conflicted" text @click="refreshVersion">刷新版本并保留输入</el-button></template></el-alert><template v-if="mode==='detail' && selected && 'username' in selected"><dl class="key-value"><dt>姓名</dt><dd>{{ selected.name }}</dd><dt>用户名</dt><dd>{{ selected.username }}</dd><dt>部门</dt><dd>{{ selected.department?.name || '未分配部门' }}</dd><dt>角色</dt><dd>{{ selected.roles.map(r=>r.name).join('、') }}</dd><dt>状态</dt><dd>{{ statusLabel(selected.status) }}</dd></dl></template><template v-else-if="mode==='status'"><p>确认{{ statusLabel(form.status) }}“{{ selected?.name }}”？</p><p class="muted">{{ kind==='users'?'停用会使该用户现有登录凭据失效。':'启停状态会影响后续业务选项，历史记录保留。' }}</p></template><el-form v-else :model="form" label-position="top" @submit.prevent="save"><template v-if="['create','edit'].includes(mode)"><el-form-item v-if="kind==='users'" label="用户名" required><el-input v-model="form.username" :disabled="mode==='edit'" maxlength="100" autocomplete="off"/></el-form-item><el-form-item :label="kind==='users'?'姓名':'名称'" required><el-input v-model="form.name" maxlength="100"/></el-form-item><el-form-item v-if="kind!=='users'" label="编码" required><el-input v-model="form.code" :disabled="mode==='edit'" maxlength="100"/></el-form-item><el-form-item v-if="kind==='users'" label="所属部门" required><el-select v-model="form.departmentId"><el-option v-for="d in departments.filter(d=>d.status==='ENABLED')" :key="d.id" :value="d.id" :label="d.name"/></el-select></el-form-item><template v-if="kind==='categories'"><el-form-item label="默认处理部门" required><el-select v-model="form.defaultDepartmentId"><el-option v-for="d in departments.filter(d=>d.status==='ENABLED')" :key="d.id" :value="d.id" :label="d.name"/></el-select></el-form-item><el-form-item label="说明"><el-input v-model="form.description" type="textarea" :rows="3"/></el-form-item></template></template><el-form-item v-if="mode==='roles' || mode==='create' && kind==='users'" label="角色" required><el-checkbox-group v-model="form.roleIds"><el-checkbox v-for="r in roles" :key="r.id" :value="r.id">{{ r.name }}</el-checkbox></el-checkbox-group></el-form-item><el-form-item v-if="mode==='password' || mode==='create' && kind==='users'" :label="mode==='password'?'新密码':'初始密码'" required><el-input v-model="form.password" type="password" show-password autocomplete="new-password"/><p class="form-help">8–72 个字符，重置后旧登录凭据失效。</p></el-form-item></el-form><template #footer><el-button :disabled="busy" @click="mode=''">{{ mode==='detail'?'关闭':'取消' }}</el-button><el-button v-if="mode!=='detail'" type="primary" :loading="busy" :disabled="conflicted" @click="save">确认保存</el-button></template></el-dialog></div></template>
